const INK = '#28256c';
// Reference-pixel space of the 560x1300 packshots -> icon units (bottle 1294 px tall = 215 units).
const PX = 'translate(53.31 18.83) scale(.166151)';

// Fruit art, drawn in packshot pixels inside the PX group.
const n = (v) => Math.round(v * 100) / 100;
const pol = (cx, cy, r, a) => `${n(cx + Math.cos(a) * r)} ${n(cy + Math.sin(a) * r)}`;
const sector = (cx, cy, r, a0, a1) => `M${cx} ${cy}L${pol(cx, cy, r, a0)}A${r} ${r} 0 ${a1 - a0 > Math.PI ? 1 : 0} 1 ${pol(cx, cy, r, a1)}Z`;
const ring = (k, f) => Array.from({length: k}, (_, i) => f(i, i * 2 * Math.PI / k)).join('');
// Each fruit: a base tone, a shadow side (lower right, light comes from the upper left) and a highlight.
const banana = (cx, cy, r, rot = 0) => `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${r}" ry="${n(r * .92)}" fill="#cdb46c"/><ellipse cx="${n(cx - r * .04)}" cy="${n(cy - r * .05)}" rx="${n(r * .91)}" ry="${n(r * .83)}" fill="#efdfae"/><ellipse cx="${n(cx - r * .12)}" cy="${n(cy - r * .13)}" rx="${n(r * .7)}" ry="${n(r * .62)}" fill="#fcf5df"/>${ring(3, (i, a) => `<path d="M${pol(cx, cy, r * .3, a + .5)}L${pol(cx, cy, r * .3, a + .5 + Math.PI)}" stroke="#d9c07a" stroke-width="${n(r * .07)}" stroke-linecap="round"/>`)}${ring(6, (i, a) => `<circle cx="${pol(cx, cy, r * .2, a)}" r="${n(r * .045)}" fill="#a8925a"/>`).replace(/cx="([\d.-]+) ([\d.-]+)"/g, 'cx="$1" cy="$2"')}</g>`;
const mango = (cx, cy, rx, ry, rot = 0) => `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#8e1a2e"/><ellipse cx="${n(cx + rx * .03)}" cy="${n(cy - ry * .04)}" rx="${n(rx * .96)}" ry="${n(ry * .95)}" fill="#d23f4a"/><ellipse cx="${n(cx - rx * .05)}" cy="${n(cy + ry * .03)}" rx="${n(rx * .9)}" ry="${n(ry * .89)}" fill="#e7861c"/><ellipse cx="${n(cx - rx * .09)}" cy="${n(cy - ry * .01)}" rx="${n(rx * .83)}" ry="${n(ry * .81)}" fill="${ref('mango')}"/><ellipse cx="${n(cx - rx * .38)}" cy="${n(cy - ry * .36)}" rx="${n(rx * .26)}" ry="${n(ry * .16)}" fill="#fff" opacity=".22" transform="rotate(-30 ${n(cx - rx * .38)} ${n(cy - ry * .36)})"/></g>`;
const MANGO_DEF = '<radialGradient id="__ID__mango" cx=".38" cy=".36" r=".7"><stop stop-color="#fde26a"/><stop offset=".55" stop-color="#f9c23a"/><stop offset="1" stop-color="#f19f26"/></radialGradient>';
const kiwi = (cx, cy, r) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#4e3818"/><circle cx="${cx}" cy="${cy}" r="${n(r * .92)}" fill="#5a8e1c"/><circle cx="${n(cx - r * .05)}" cy="${n(cy - r * .05)}" r="${n(r * .84)}" fill="#82b82a"/><circle cx="${n(cx - r * .14)}" cy="${n(cy - r * .16)}" r="${n(r * .46)}" fill="#a8d24c" opacity=".75"/><path d="${ring(18, (i, a) => `M${pol(cx, cy, r * .52, a)}L${pol(cx, cy, r * .8, a)}`)}" stroke="#c6e27a" stroke-width="2" opacity=".55"/>${ring(18, (i, a) => `<ellipse cx="${n(cx + Math.cos(a) * r * .41)}" cy="${n(cy + Math.sin(a) * r * .41)}" rx="${n(r * .032)}" ry="${n(r * .085)}" transform="rotate(${n(a * 180 / Math.PI + 90)} ${n(cx + Math.cos(a) * r * .41)} ${n(cy + Math.sin(a) * r * .41)})" fill="#1b220c"/>`)}<ellipse cx="${cx}" cy="${cy}" rx="${n(r * .27)}" ry="${n(r * .22)}" fill="#edefc6"/>`;
// Orange slice: rind, pith, ten segments with their membranes; half=true keeps only the lower half (a half slice).
const orange = (cx, cy, r, rot = 0, half = false) => {
  const a0 = half ? 0 : -Math.PI, k = half ? 5 : 10, sp = Math.PI / 5;
  const disc = (rr, f, dx = 0) => half ? `<path d="${sector(n(cx + dx), n(cy + dx), rr, 0, Math.PI)}" fill="${f}"/>` : `<circle cx="${n(cx + dx)}" cy="${n(cy + dx)}" r="${rr}" fill="${f}"/>`;
  return `<g transform="rotate(${rot} ${cx} ${cy})">${disc(r, '#d9660a')}${disc(n(r * .96), '#f48e1e', -r * .03)}${disc(n(r * .88), '#fde4ac')}${Array.from({length: k}, (_, i) => `<path d="${sector(cx, cy, n(r * .82), n(a0 + i * sp + .05), n(a0 + (i + 1) * sp - .05))}" fill="${i % 2 ? '#f7a01e' : '#fab232'}"/>`).join('')}<circle cx="${cx}" cy="${cy}" r="${n(r * .1)}" fill="#fde4ac"/><path d="${sector(cx, cy, n(r * .8), half ? 2.2 : 3.4, half ? 2.9 : 4.3)}" fill="#fff" opacity=".22"/></g>`;
};
const pineapple = (cx, cy, r) => `<path d="M${Array.from({length: 28}, (_, i) => pol(cx, cy, i % 2 ? r * .92 : r, i * Math.PI / 14)).join('L')}Z" fill="#6e4f1a"/><circle cx="${cx}" cy="${cy}" r="${n(r * .9)}" fill="#d9a21e"/><circle cx="${n(cx - r * .04)}" cy="${n(cy - r * .04)}" r="${n(r * .84)}" fill="#f3c534"/><circle cx="${n(cx - r * .14)}" cy="${n(cy - r * .14)}" r="${n(r * .5)}" fill="#fbe274" opacity=".8"/><path d="${ring(12, (i, a) => `M${pol(cx, cy, r * .24, a)}L${pol(cx, cy, r * .8, a)}`)}" stroke="#fdeca8" stroke-width="4" opacity=".7"/>${ring(14, (i, a) => `<circle cx="${n(cx + Math.cos(a) * r * .87)}" cy="${n(cy + Math.sin(a) * r * .87)}" r="${n(r * .03)}" fill="#8a5a1a"/>`)}<circle cx="${cx}" cy="${cy}" r="${n(r * .18)}" fill="#fcefb8"/>`;
// Strawberry, whole or halved, in a 100x120 local box scaled by s.
const berry = (x, y, rot, s, half) => `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})"><path d="M-48 -30Q-50 -64 0 -62Q52 -64 50 -28Q46 20 6 58Q-4 66 -14 52Q-46 16 -48 -30Z" fill="#c41f29"/><path d="M50 -28Q46 20 6 58Q-4 66 -14 52Q20 20 30 -30Q36 -56 26 -62Q52 -58 50 -28Z" fill="#951520"/>${half
  ? '<path d="M-38 -28Q-38 -52 0 -50Q40 -52 40 -26Q36 14 4 44Q-4 50 -12 40Q-38 12 -38 -28Z" fill="#ec5a5a"/><path d="M-26 -30Q-24 -44 0 -42Q26 -44 26 -26Q22 6 2 30Q-24 4 -26 -30Z" fill="#f79a92"/><path d="M-12 -36Q0 -42 12 -36Q14 -4 2 22Q-12 -4 -12 -36Z" fill="#fde6dc"/>'
  : `<path d="M-38 -46Q-22 -58 4 -56" stroke="#ff8a7a" stroke-width="8" fill="none" stroke-linecap="round" opacity=".65"/>${Array.from({length: 17}, (_, i) => `<ellipse cx="${-32 + (i % 5) * 15 + (Math.floor(i / 5) % 2) * 7}" cy="${-38 + Math.floor(i / 5) * 22}" rx="2.8" ry="3.8" fill="#f7d76e"/>`).join('')}`}
<path d="M-30 -58L-46 -74L-16 -68L-6 -84L8 -66L36 -76L26 -56Z" fill="#2f6e22"/><path d="M-30 -58L-16 -68L-6 -84L0 -64Z" fill="#5aa23a"/></g>`;
const greenAppleSlice = `<path d="M150 1046Q166 996 232 984Q282 980 286 1006Q272 1060 200 1068Q160 1070 150 1046Z" fill="#5f9a2a"/><path d="M156 1040Q172 1000 232 990Q276 988 280 1006Q264 1040 214 1052Q170 1058 156 1040Z" fill="#8cc44a"/><path d="M164 1032Q182 1004 232 996Q268 996 270 1008Q254 1034 212 1042Q178 1046 164 1032Z" fill="#e2ebba"/><path d="M174 1024Q192 1006 232 1002Q256 1002 258 1008Q228 1012 174 1024Z" fill="#f6f8dc"/>`;
const broccoli = `<path d="M136 1072L150 1040L164 1036L158 1074Z" fill="#8ab04e"/><path d="M146 1070L154 1042L162 1040L156 1072Z" fill="#b8d27e"/>${[[112, 1010, 26], [138, 994, 28], [166, 1008, 24], [126, 1034, 22], [154, 1030, 20]].map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#2c5f1e"/><circle cx="${x - 3}" cy="${y - 3}" r="${n(r * .8)}" fill="#4a8a30"/><circle cx="${x - 7}" cy="${y - 7}" r="${n(r * .4)}" fill="#76ae46"/>`).join('')}`;
const spinach = `<path d="M222 920Q226 868 288 862Q314 882 306 916Q290 946 246 944Q226 940 222 920Z" fill="#1f4c1c"/><path d="M226 914Q232 872 286 868Q306 886 298 912Q282 936 248 936Q230 932 226 914Z" fill="#2f6a29"/><path d="M234 930Q262 900 296 870" stroke="#5a9a48" stroke-width="3.5" fill="none"/>`;

// The bottle: body, label (clipped), shade, highlights, then the ribbed cap.
function bottle({slug, title, juice, label, defs}) {
  const ribs = Array.from({length: 22}, (_, i) => `M${(76.6 + i * 2.2).toFixed(2)} 22.4V35.6`).join('');
  return wrap(slug, title, `${shadow(40)}
<path d="${BODY}" fill="${ref('juice')}"/>
<g clip-path="${ref('bodyclip')}">
<path d="M60 70.8Q100 73.4 140 70.8" fill="none" stroke="#000" stroke-opacity=".14" stroke-width=".8"/>
<path d="M60 214.6Q100 216.6 140 214.6" fill="none" stroke="#000" stroke-opacity=".16" stroke-width=".9"/>
<path d="M60 228.6Q100 230.4 140 228.6" fill="none" stroke="#000" stroke-opacity=".1" stroke-width=".7"/>
${label}
<path d="${BODY}" fill="${ref('shade')}" opacity=".55"/>
<path d="M67.4 82V208" fill="none" stroke="#fff" stroke-opacity=".3" stroke-width="2.2" stroke-linecap="round"/>
<path d="M68 62Q71 56 77 52" fill="none" stroke="#fff" stroke-opacity=".28" stroke-width="1.6" stroke-linecap="round"/>
<path d="M66.4 218V228" fill="none" stroke="#fff" stroke-opacity=".22" stroke-width="1.6" stroke-linecap="round"/>
<path d="M132.4 84V206" fill="none" stroke="#fff" stroke-opacity=".12" stroke-width="1.5" stroke-linecap="round"/>
</g>
<path d="${CAP}" fill="${ref('cap')}"/>
<path d="${ribs}" stroke="#1f1f8a" stroke-opacity=".35" stroke-width=".7"/>
<path d="M75 36.6Q100 37.6 125 36.6" fill="none" stroke="#1d1d80" stroke-opacity=".55" stroke-width=".7"/>
<path d="M77.4 21.4Q100 19.6 122.6 21.4" fill="none" stroke="#9a9af0" stroke-opacity=".6" stroke-width=".8"/>
<path d="M79 23.5V34.5" stroke="#fff" stroke-opacity=".3" stroke-width="1.4" stroke-linecap="round"/>
`, `<clipPath id="__ID__bodyclip"><path d="${BODY}"/></clipPath>
<linearGradient id="__ID__juice"><stop stop-color="${juice[2]}"/><stop offset=".1" stop-color="${juice[0]}"/><stop offset=".3" stop-color="${juice[1]}"/><stop offset=".85" stop-color="${juice[1]}"/><stop offset="1" stop-color="${juice[2]}"/></linearGradient>
<linearGradient id="__ID__cap"><stop stop-color="#2a2a9c"/><stop offset=".12" stop-color="#6464e0"/><stop offset=".3" stop-color="#4a4ad0"/><stop offset=".8" stop-color="#4040c2"/><stop offset="1" stop-color="#25258e"/></linearGradient>
${defs}`);
}

const banner = (dx = 0, dy = 0, s = 1) => `<g${dx || dy || s !== 1 ? ` transform="translate(${dx} ${dy}) scale(${s})"` : ''}><path d="${BANNER}" fill="${INK}" fill-rule="evenodd"/><path d="${WORDMARK}" fill="#fff" fill-rule="evenodd"/><path d="${LEAF}" fill="#c1d72e" fill-rule="evenodd"/></g>`;
const labelBg = (y0, y1) => `<path d="M58 ${y0}H142V${y1}H58Z" fill="${ref('lab')}"/><path d="M58 ${n(y0 + (y1 - y0) * .4)}H142V${y1}H58Z" fill="${ref('labB')}"/><path d="M58 ${n(y0 + .3)}H142M58 ${n(y1 - .3)}H142" stroke="#000" stroke-opacity=".12" stroke-width=".6"/>`;
const labGrad = (c) => `<linearGradient id="__ID__lab"><stop offset=".08" stop-color="${c[0]}"/><stop offset=".5" stop-color="${c[1]}"/><stop offset=".92" stop-color="${c[2]}"/></linearGradient><linearGradient id="__ID__labB" x2="0" y2="1"><stop stop-color="${c[3]}" stop-opacity="0"/><stop offset="1" stop-color="${c[3]}"/></linearGradient>`;
const small = (x, y, s, w, fill, size = 4.8) => text(x, y, s, size, fill, `font-weight="bold" textLength="${w}" lengthAdjust="spacingAndGlyphs"`);

// The Machine label (2025 design): banner, BOOSTED SMOOTHIE, flavor name, swirl, nutrient box, calories, fruit, badge.
function machine({slug, title, juice, lab, acc, titlePath, cals, side, fruit, mangoDef = true}) {
  const label = `${labelBg(83.8, 211.2)}
${banner()}
<path d="${BOOSTED}" fill="${INK}" fill-rule="evenodd"/>
<path d="${titlePath}" fill="${acc}" fill-rule="evenodd"/>
<path d="${SWIRL}" fill="${INK}" fill-rule="evenodd"/>
${side(acc)}
<g transform="${PX}">${fruit}</g>
<path d="${BOX}" fill="${acc}"/><path d="${BOX_TEXT}" fill="#fff" fill-rule="evenodd"/>
<path d="${cals}" fill="${INK}" fill-rule="evenodd"/>
<rect x="112.2" y="190.2" width="18.6" height="15.4" rx="1.2" fill="${acc}"/><path d="${BADGE_TEXT}" fill="#fff" fill-rule="evenodd"/>
<path d="${RING}" fill="${INK}" fill-rule="evenodd"/>
${small(78.2, 205.3, '15.2 FL OZ (450 mL)', 21.6, acc, 4.6)}`;
  return bottle({slug, title, juice, label, defs: labGrad(lab) + (mangoDef ? MANGO_DEF : '')});
}

